{#- =====================================================================
    Payment Entry -> Nepal bank cheque overlay

    Prints DIRECTLY onto the bare cheque. The cheque leaf goes into the tray
    alone, LOGO EDGE FIRST.

    DEFAULT (sheet=a4): the page is declared a normal A4, but the cheque
    content is placed where a bare cheque physically sits in the tray. The
    LBP2900 is CENTRE-FED -- a narrow sheet registers to the middle of the
    tray -- so the cheque's left edge lands at (210 - 88.9)/2 = 60.55mm, and
    its leading edge is the top of the page, so MY = 0.
    This means you can leave the print dialog on plain A4: no custom paper
    size, no special CUPS queue. Nothing is centred on the page "for looks" --
    60.55 is where the paper actually is.

    ALIGN: &align=left if the printer registers narrow paper to the LEFT edge
    of the tray instead of the centre (then MX = 0).

    sheet=cheque: emit a true 88.9 x 190.5 mm page instead. Only use this if
    a matching custom paper size is actually selected in the print dialog,
    otherwise the print path re-centres the small page and everything misses.

    &cheque_guide=1 draws the outline + corner marks for a dry run on paper.

    Field positions below are millimetres from the CHEQUE's own top-left
    corner, so they match how you measure on the cheque. Nudge and reprint.
    ===================================================================== -#}

{%- set CHEQUE_W = 190.5 -%}{%- set CHEQUE_H = 88.9 -%}
{#- ---- Cheque Print Alignment settings (Setup > Cheque Print Alignment) ----
    Guarded with exists() so the format still renders on a site where the
    doctype has not been migrated in yet. URL params still win over it. -#}
{%- if frappe.db.exists("DocType", "Cheque Print Alignment") -%}
  {%- set CAL_RIGHT = frappe.db.get_single_value("Cheque Print Alignment", "move_right") or 0.0 -%}
  {%- set CAL_DOWN  = frappe.db.get_single_value("Cheque Print Alignment", "move_down") or 0.0 -%}
  {%- set CAL_ROT   = frappe.db.get_single_value("Cheque Print Alignment", "rotation") -%}
  {%- set CAL_ALIGN = frappe.db.get_single_value("Cheque Print Alignment", "tray_align") -%}
  {%- set CAL_SHEET = frappe.db.get_single_value("Cheque Print Alignment", "sheet_mode") -%}
{%- else -%}
  {%- set CAL_RIGHT = 0.0 -%}{%- set CAL_DOWN = 0.0 -%}
  {%- set CAL_ROT = None -%}{%- set CAL_ALIGN = None -%}{%- set CAL_SHEET = None -%}
{%- endif -%}

{#- URL param > saved setting > built-in default -#}
{%- set SHEET = frappe.form_dict.get("sheet") or CAL_SHEET or "a4" -%}
{%- set ALIGN = frappe.form_dict.get("align") or CAL_ALIGN or "centre" -%}
{%- if SHEET == "cheque" -%}
  {%- set PAGE_W = CHEQUE_H -%}{%- set PAGE_H = CHEQUE_W -%}
  {%- set MX = 0.0 -%}{%- set MY = 0.0 -%}     {#- true cheque-sized page -#}
{%- else -%}
  {%- set PAGE_W = 210.0 -%}{%- set PAGE_H = 297.0 -%}
  {%- if ALIGN == "left" -%}{%- set MX = 0.0 -%}
  {%- else -%}{%- set MX = (210.0 - CHEQUE_H) / 2 -%}{%- endif -%}
  {%- set MY = 0.0 -%}                         {#- leading edge of the cheque = top of the page -#}
{%- endif -%}

{#- =====================================================================
    PRINTER ALIGNMENT -- moves the whole cheque block on the paper.

    Set this in the UI:  Cheque Print Alignment  (a Settings single)
      Move Right (mm) : + right, - left
      Move Down  (mm) : + down,  - up

    For quick trials without saving, add &dx=2.5&dy=-1 to the print URL.
    URL values are ADDED ON TOP of the saved ones.

    Never change the field coordinates below to fix printer misalignment --
    those are measured from the cheque and are the same on every printer.
    ===================================================================== -#}
{%- set MX = MX + CAL_RIGHT + ((frappe.form_dict.get("dx") or 0)|float) -%}
{%- set MY = MY + CAL_DOWN  + ((frappe.form_dict.get("dy") or 0)|float) -%}
{%- set FONT = 11 -%}
{%- set ROTATE = (frappe.form_dict.get("rotate") or CAL_ROT or 90)|int -%}   {#- 90 or 270 -- flip if text prints upside down -#}
{%- set USE_BS = 0 -%}                        {#- 1 = Nepali BS date, 0 = posting_date as-is -#}

{#- ---- field positions: mm from the CHEQUE top-left ---- -#}
{%- set DATE_X = 138.0 -%}{%- set DATE_Y = 10.0 -%}{%- set DATE_GAP = 3.8 -%}
{%- set PAYEE_X = 44.0 -%}{%- set PAYEE_Y = 22.0 -%}
{%- set WORDS_X = 29.0 -%}{%- set WORDS_Y = 28.5 -%}{%- set WORDS_W = 100.0 -%}{%- set WORDS_LH = 7.0 -%}
{%- set FIG_X = 142.6 -%}{%- set FIG_Y = 31.0 -%}{%- set FIG_W = 50.0 -%}

{#- ---- date digits DDMMYYYY ---- -#}
{%- if USE_BS -%}
  {%- set _ds = bs_date_str(doc.posting_date, "") -%}
  {%- set date_digits = _ds[6:8] ~ _ds[4:6] ~ _ds[0:4] -%}
{%- else -%}
  {%- set _g = frappe.utils.getdate(doc.posting_date) -%}
  {%- set date_digits = "%02d"|format(_g.day) ~ "%02d"|format(_g.month) ~ "%04d"|format(_g.year) -%}
{%- endif -%}

{%- set _words = frappe.utils.money_in_words(doc.paid_amount, doc.paid_from_account_currency or "NPR") -%}

{#- ---- payee name = the party's name (blank when there is no party, e.g. internal transfer) ---- -#}
{%- set _payee = doc.party_name or doc.party or "" -%}

{%- set GUIDE = frappe.form_dict.get("cheque_guide") -%}

{#- rotated footprint on the A4, and cheque top-left placement so the rotated box lands at MX,MY -#}
{%- set FP_W = CHEQUE_H -%}{%- set FP_H = CHEQUE_W -%}
{%- if ROTATE == 270 -%}
  {%- set CHEQUE_LEFT = MX -%}{%- set CHEQUE_TOP = MY + CHEQUE_W -%}
{%- else -%}
  {%- set CHEQUE_LEFT = MX + CHEQUE_H -%}{%- set CHEQUE_TOP = MY -%}
{%- endif -%}

<style>
  @page { size: {{ PAGE_W }}mm {{ PAGE_H }}mm; margin: 0; }
  html, body { margin: 0; padding: 0; }
  #cheque-page {
    position: relative; width: {{ PAGE_W }}mm; height: {{ PAGE_H }}mm; overflow: hidden;
    font-family: "DejaVu Sans", Arial, sans-serif;
  }
  #cheque {
    position: absolute;
    width: {{ CHEQUE_W }}mm; height: {{ CHEQUE_H }}mm;
    font-size: {{ FONT }}pt; color: #000; line-height: 1.1;
    transform: rotate({{ ROTATE }}deg); transform-origin: top left;
  }
  #cheque .f { position: absolute; white-space: nowrap; }
  #cheque .date {
    font-family: "DejaVu Sans Mono", "Courier New", monospace;
    letter-spacing: {{ DATE_GAP }}mm; font-weight: 600;
  }
  #cheque .words { white-space: normal; width: {{ WORDS_W }}mm; line-height: {{ WORDS_LH }}mm; }
  #cheque .fig { width: {{ FIG_W }}mm; text-align: left; font-weight: 600; }
  {%- if GUIDE %}
  #cheque { outline: 0.35mm dashed #0060cc; }
  .cmark { position: absolute; width: 7mm; height: 7mm; }
  #note {
    position: absolute; left: {{ MX }}mm; top: {{ MY + FP_H + 8 }}mm;
    width: 185mm; font-size: 10pt; color: #c00; line-height: 1.4;
  }
  {%- endif %}
</style>

<div id="cheque-page">
  {%- if GUIDE %}
    {#- L-shaped corner marks just OUTSIDE the cheque box, so they stay visible next to the cheque -#}
    <div class="cmark" style="left:{{ MX-1 }}mm; top:{{ MY-1 }}mm; border-left:0.4mm solid #c00; border-top:0.4mm solid #c00;"></div>
    <div class="cmark" style="left:{{ MX+FP_W-6 }}mm; top:{{ MY-1 }}mm; border-right:0.4mm solid #c00; border-top:0.4mm solid #c00;"></div>
    <div class="cmark" style="left:{{ MX-1 }}mm; top:{{ MY+FP_H-6 }}mm; border-left:0.4mm solid #c00; border-bottom:0.4mm solid #c00;"></div>
    <div class="cmark" style="left:{{ MX+FP_W-6 }}mm; top:{{ MY+FP_H-6 }}mm; border-right:0.4mm solid #c00; border-bottom:0.4mm solid #c00;"></div>
    <div id="note">
      &#9654; Alignment guide &mdash; the dashed box is where the bare cheque sits in the tray.
      Feed the cheque <b>logo edge first</b>. Reprint <b>without</b> &amp;cheque_guide=1 for the real run.<br>
      Paper size <b>A4</b> is correct. Print at 100% / Actual Size, margins none, headers/footers off.
    </div>
  {%- endif %}

  <div id="cheque" style="left:{{ CHEQUE_LEFT }}mm; top:{{ CHEQUE_TOP }}mm;">
    {%- if GUIDE %}<div class="ruler"></div>{%- endif %}
    <div class="f date" style="left:{{ DATE_X }}mm; top:{{ DATE_Y }}mm;">{{ date_digits }}</div>
    <div class="f" style="left:{{ PAYEE_X }}mm; top:{{ PAYEE_Y }}mm;">{{ _payee }}</div>
    <div class="f words" style="left:{{ WORDS_X }}mm; top:{{ WORDS_Y }}mm;">{{ _words }}</div>
    <div class="f fig" style="left:{{ FIG_X }}mm; top:{{ FIG_Y }}mm;">{{ "{:,.2f}".format(doc.paid_amount) }}</div>
  </div>
</div>
